class Solution {
    func longestSubarray(_ nums: [Int], _ limit: Int) -> Int {
        var map = [Int: Int]()
        var sortedKeys = [Int]()
        var l = 0
        var res = 0

        for r in 0..<nums.count {
            let x = nums[r]
            if map[x] == nil {
                sortedKeys.append(x)
                sortedKeys.sort()
            }
            map[x, default: 0] += 1

            while let maxKey = sortedKeys.last, let minKey = sortedKeys.first,
                  maxKey - minKey > limit {
                let y = nums[l]
                l += 1
                map[y]! -= 1
                if map[y] == 0 {
                    map.removeValue(forKey: y)
                    if let idx = sortedKeys.firstIndex(of: y) {
                        sortedKeys.remove(at: idx)
                    }
                }
            }

            res = max(res, r - l + 1)
        }
        return res
    }
}
